from typing import List


def max_score(grid: List[List[int]]) -> int:
    """ Given a 2D matrix of positive integers, select one or more cells such that:
    - No two selected cells are in the same row
    - The values in the selected cells are unique

    Return the maximum sum of values you can achieve.

    Args:
        grid: A 2D list where 1 <= len(grid), len(grid[i]) <= 10 and 1 <= grid[i][j] <= 100

    >>> max_score([[1,2,3],[4,3,2],[1,1,1]])
    8
    >>> max_score([[8,7,6],[8,3,2]])
    15
    """
    n = len(grid)
    # For each row, keep only the maximum value for each distinct number in that row
    row_max = []
    for row in grid:
        d = {}
        for v in row:
            if v not in d or d[v] < v:
                d[v] = v
        row_max.append(d)

    # DP over rows, state is bitmask of used values (values 1..100)
    # dp[mask] = max sum achievable using the set of values in mask after processing some rows
    # We process rows one by one. For each row, we can either skip it or pick one value from it.
    # Since values are 1..100, mask can be up to 2^100 which is too large.
    # However, we can use a dictionary to store only reachable states.

    dp = {0: 0}

    for i in range(n):
        new_dp = dict(dp)  # option to skip this row
        for mask, val in dp.items():
            for v in row_max[i]:
                bit = 1 << (v - 1)
                if mask & bit == 0:
                    new_mask = mask | bit
                    new_val = val + v
                    if new_mask not in new_dp or new_dp[new_mask] < new_val:
                        new_dp[new_mask] = new_val
        dp = new_dp

    return max(dp.values())
